from pathlib import Path

from app.services import users

_DATA_DIR = Path(__file__).resolve().parent.parent.parent / "data"


def _valid_segments(raw: str) -> list[str] | None:
    """Split a request path into safe segments, or return None when invalid."""
    segments = raw.split("/")
    if any(segment == "" or segment == "." or segment == ".." for segment in segments):
        return None
    return segments


def handle_line_count(params: dict) -> tuple[int, dict]:
    raw = params.get("path")
    if not isinstance(raw, str) or not raw:
        return 400, {"error": "invalid path"}
    segments = _valid_segments(raw)
    if segments is None:
        return 400, {"error": "invalid path"}
    data_dir = _DATA_DIR.resolve()
    target = data_dir.joinpath(*segments)
    if not target.resolve().is_relative_to(data_dir):
        return 400, {"error": "invalid path"}
    if not target.is_file():
        return 404, {"error": "not found"}
    text = target.read_bytes().decode("utf-8", errors="replace")
    lines = text.count("\n")
    if text and not text.endswith("\n"):
        lines += 1
    return 200, {"lines": lines}


